code_example:
int a = 5, b = 10;
int temp = a;
a = b;
b = temp;

// Using std::swap (C++)
std::swap(a, b);

// Swapping without temp (XOR, integer only)
a = a ^ b;
b = a ^ b;
a = a ^ b;

// Swapping Pointers (Generic)
void* ptr_a = &a;
void* ptr_b = &b;
void* ptr_temp = ptr_a;
ptr_a = ptr_b;
ptr_b = ptr_temp;
